function addWire(a,b,short){if(a.c==b.c&&a.t==b.t)return false;if(CK.wires.some(w=>!w.broken&&(w.a.c==a.c&&w.a.t==a.t&&w.b.c==b.c&&w.b.t==b.t||w.b.c==a.c&&w.b.t==a.t&&w.a.c==b.c&&w.a.t==b.t)))return false;let i=CK.wires.length+1;while(CK.wires.some(w=>w.id=="w"+i))i++;CK.wires.push({id:"w"+i,a,b,...(short?{short:true}:{})});keep();return true}
