  if(cEl){const c=CK.comps.find(x=>x.id==cEl.dataset.c);if(!c)return;PEND=null;SEL={k:"c",id:c.id};TAB="props";DRAG={id:c.id,dx:p.x-c.x,dy:p.y-c.y,moved:false,sx:ev.clientX,sy:ev.clientY,tap:SIM};sv.setPointerCapture(ev.pointerId);draw();return}
