const wpath=w=>{const ca=CK.comps.find(c=>c.id==w.a.c),cb=CK.comps.find(c=>c.id==w.b.c);if(!ca||!cb)return"";const [x1,y1]=tpos(ca,w.a.t),[x2,y2]=tpos(cb,w.b.t);return w.flip?`M${x1} ${y1}V${y2}H${x2}`:`M${x1} ${y1}H${x2}V${y2}`};
function toggle(c){const s=c.state||(c.state={});switch(c.type){case"switch":case"thermostat":case"bimetal":s.closed=!s.closed;toast(`${c.name||c.id}: ${s.closed?"مغلق":"مفتوح"}`);return true;case"fuse":case"thermalFuse":s.blown=!s.blown;toast(`${c.name||c.id}: ${s.blown?"محروق":"سليم"}`);return true;case"overload":s.tripped=!s.tripped;toast(`${c.name||c.id}: ${s.tripped?"فاصل":"مغلق"}`);return true;case"timer":s.pos=s.pos=="defrost"?"cool":"defrost";return true;case"spdt":s.pos=s.pos=="b"?"a":"b";return true;case"ptc":s.hot=!s.hot;return true;case"vac":case"vdc":s.on=s.on===false;return true}return false}
